<script setup>import {router} from '@inertiajs/vue3'; import AppLayout from '../../Layouts/AppLayout.vue'; import PaginationLinks from '../../components/ui/PaginationLinks.vue'; const props=defineProps({type:String,from:String,to:String,summary:Object,data:Object,clients:Array,sellers:Array,types:Object,exportUrl:String}); const filters={report_type:props.type,start_date:props.from,end_date:props.to}; const refresh=()=>router.get('/reportes',filters); const money=v=>new Intl.NumberFormat('es-NI',{style:'currency',currency:'NIO'}).format(Number(v||0)); const label=k=>k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()); const scalarEntries=row=>Object.entries(row).filter(([k,v])=>!['id','created_at','updated_at'].includes(k)&&['string','number'].includes(typeof v)).slice(0,6);</script>
<template><AppLayout title="Reportes financieros" eyebrow="Análisis" description="Consultas operativas y exportación CSV sobre datos reales."><div class="card mb-4 grid gap-3 p-4 md:grid-cols-3 xl:grid-cols-6"><label class="field-label">Reporte<select v-model="filters.report_type" class="control" @change="refresh"><option v-for="(name,key) in types" :key="key" :value="key">{{name}}</option></select></label><label class="field-label">Desde<input v-model="filters.start_date" type="date" class="control" @change="refresh"></label><label class="field-label">Hasta<input v-model="filters.end_date" type="date" class="control" @change="refresh"></label><label class="field-label">Cliente<select v-model="filters.client" class="control" @change="refresh"><option value="">Todos</option><option v-for="client in clients" :key="client.id" :value="client.id">{{client.full_name}}</option></select></label><label class="field-label">Gestor<select v-model="filters.seller" class="control" @change="refresh"><option value="">Todos</option><option v-for="seller in sellers" :key="seller.id" :value="seller.id">{{seller.display_name}}</option></select></label><div class="flex items-end"><a :href="`${exportUrl}?${new URLSearchParams(filters)}`" class="btn-primary">Exportar CSV</a></div></div><section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><div v-for="(value,key) in summary" :key="key" class="live-metric" data-tone="blue"><p>{{label(key)}}</p><strong>{{String(key).includes('amount')||String(key).includes('total')?money(value):value}}</strong></div></section><section class="card mt-4 overflow-hidden"><div class="divide-y"><article v-for="row in data.data" :key="row.id" class="p-4"><div class="grid gap-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="([key,value]) in scalarEntries(row)" :key="key"><p class="text-[10px] uppercase text-slate-400">{{label(key)}}</p><p class="mt-1 text-xs font-semibold">{{value}}</p></div></div></article><p v-if="!data.data.length" class="empty-state">No hay datos para los filtros seleccionados.</p></div><PaginationLinks :links="data.links"/></section></AppLayout></template>
